def refs():
    return [{**s, "subject": "science", "locator": "血液組成與功能、心臟腔室與瓣膜、動脈靜脈微血管、肺循環與體循環、淋巴回流、抽血與運動情境", "observedPattern": "公立學校公開生物科試題常以心臟圖、血管序列、抽血或運動情境及淋巴回流判讀，要求由流向、含氧量、構造與功能交叉推論；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-db-iv-2-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供心臟圖、血管序列、抽血／運動情境與淋巴回流的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "血液中紅血球最主要的運輸任務為何？", {"A": "利用血紅素攜帶氧，將氧運送到身體各處細胞", "B": "製造消化酵素並把食物切碎", "C": "以瓣膜控制心臟內血液方向", "D": "把所有病原體直接分解成水"}, "紅血球含血紅素，主要負責攜帶氧並參與二氧化碳運輸；消化、瓣膜與免疫防禦不是紅血球的主要功能。", "先把血液成分與功能配對，再排除屬於消化、心臟構造或白血球的敘述。", ["圈出題目問的是血液中的紅血球。", "連結紅血球內血紅素與氧的攜帶。", "確認運輸對象是身體各處細胞。", "排除酵素、瓣膜與病原體分解等其他系統功能。", "所以選 A。"], "easy"),
    make(2, "白血球與血小板的功能分別較接近哪一組？", {"A": "白血球參與防禦；血小板協助凝血止血", "B": "白血球攜帶氧；血小板分泌膽汁", "C": "白血球形成瓣膜；血小板負責消化澱粉", "D": "白血球只運送脂肪；血小板控制呼吸頻率"}, "白血球可辨認並對抗病原體，血小板在血管受傷時參與凝血；攜氧主要是紅血球，膽汁則由肝臟製造。", "功能配對題先找每個成分的直接任務，不以『都在血液中』推論功能相同。", ["分別讀取白血球與血小板兩個主詞。", "將白血球連到免疫防禦。", "將血小板連到傷口凝血與止血。", "排除紅血球、消化腺與呼吸調節的功能。", "所以選 A。"], "easy"),
    make(3, "心臟瓣膜在循環系統中的主要作用是什麼？", {"A": "讓血液大致維持單向流動，減少回流", "B": "把血液中的氧直接製造出來", "C": "讓微血管進行所有物質交換", "D": "把血球從血漿中全部濾除"}, "瓣膜在心房、心室或心室與大血管之間依壓力差開關，主要用來防止血液逆流；它不負責製氧或過濾血球。", "構造功能題要先問這個構造控制的是方向、成分還是交換，再對照選項。", ["定位瓣膜在心臟內的構造角色。", "確認它能開關的直接效果是阻止逆流。", "把單向流動與循環效率連起來。", "排除製氧、微血管交換和過濾血球等功能。", "所以選 A。"], "easy"),
    make(4, "若以『心臟→血管→組織→血管→心臟』描述體循環，物質交換主要發生在哪一段？", {"A": "心臟四個腔室內", "B": "連接心臟的大動脈內", "C": "組織附近的微血管網", "D": "只在肺泡外的氣管內"}, "微血管壁薄且分布在組織附近，適合讓氧、二氧化碳、養分與代謝廢物在血液和組織間交換。", "先找『交換』的線索，再依血管構造與所在位置判斷，而不是選血流量最大的血管。", ["圈出題目問的是物質交換位置。", "比較大動脈、微血管與心臟腔室的功能。", "確認微血管壁薄且貼近組織細胞。", "排除只負責輸送或不在體循環交換處的構造。", "所以選 C。"], "medium"),
    make(5, "下列哪條路徑最能表示含氧量較高的血液由肺回到心臟，再送往全身？", {"A": "肺靜脈→左心房→左心室→主動脈", "B": "肺動脈→右心房→右心室→主動脈", "C": "上腔靜脈→左心房→右心室→肺靜脈", "D": "主動脈→右心房→右心室→肺動脈"}, "肺部氧合後的血液經肺靜脈回到左心房，再進入左心室，最後由主動脈送往全身；判斷時要用流向而非單看動脈或靜脈名稱。", "循環路徑題先標示來源與目的地，再依腔室順序和血管連接核對。", ["先定位含氧血的來源是肺。", "確認肺回心臟使用肺靜脈。", "依序通過左心房與左心室。", "確認離開左心室的血管是主動脈。", "所以選 A。"], "medium"),
    make(6, "把手臂上方綁緊後，靜脈較容易浮出以便抽血，最合理的原因是？", {"A": "束帶阻礙靜脈回流，使下游靜脈暫時充血，但動脈供血仍可進入", "B": "束帶讓靜脈內血液全部流回心臟，所以血管變粗", "C": "束帶把血液改送進淋巴管，靜脈因此消失", "D": "束帶使紅血球在皮膚外製造，血管才會浮出"}, "適度束帶可先阻礙較表淺靜脈回流，動脈血仍流入，使靜脈充血明顯；這也解釋了抽血常選表淺靜脈。", "情境題用『進入量與離開量』比較，不把所有血管都當成同向受阻。", ["辨認題目觀察的是手臂表淺靜脈。", "比較動脈流入與靜脈回流的方向。", "確認回流受阻會造成局部血液暫時累積。", "排除血液全回心臟、改進淋巴管與體外製造等說法。", "所以選 A。"], "medium"),
    make(7, "運動後心搏加快，對身體最直接的幫助為何？", {"A": "提高血液輸送氧與養分、帶走二氧化碳與代謝廢物的速率", "B": "讓細胞不再需要氧，因而停止呼吸作用", "C": "把氧氣在心臟內製造出來", "D": "使所有血管同時關閉以保存血液"}, "運動中的肌肉需要更多氧與養分，也產生較多二氧化碳與廢物；心搏加快可提高循環運輸速率，但不會製造氧。", "生理調節題要把需求增加與循環功能連起來，再排除把運輸說成製造的選項。", ["先辨認運動時肌肉的需求變化。", "列出需要送入與帶走的物質。", "連結心搏加快與單位時間的輸送量。", "排除停止呼吸、製造氧與關閉血管等矛盾敘述。", "所以選 A。"], "easy"),
    make(8, "淋巴循環與血液循環的關係，下列何者正確？", {"A": "部分組織液進入淋巴管形成淋巴，最後回到靜脈以維持體液回收", "B": "淋巴只在動脈內流動，最後由心室製造", "C": "淋巴管完全取代微血管進行所有氣體交換", "D": "淋巴流出身體後才會被血液回收"}, "部分由微血管濾出的組織液會進入淋巴管成為淋巴，經淋巴管與淋巴結後回到靜脈，協助回收體液；它不是動脈或心室製造的液體。", "先追蹤液體來源、進入管道與回流終點，避免只背『淋巴』名稱。", ["確認組織液是淋巴的來源之一。", "找出液體進入淋巴管的轉折。", "確認淋巴最後回到靜脈與血液循環。", "排除動脈內流動、取代微血管與流出體外的說法。", "所以選 A。"], "medium"),
    make(9, "若某段血管內血液流向是『由心臟離開，經過物質交換處，再回到心臟』，哪個判斷最可靠？", {"A": "先依流向判定靠近心臟的兩段，再用含氧量與器官位置判斷是體循環或肺循環", "B": "只要血管叫動脈，就一定含氧量高且離開肺", "C": "只要血管叫靜脈，就一定直接進入左心房", "D": "血液流速最大的位置一定是物質交換處"}, "動脈與靜脈的定義是相對心臟的流向，不等於固定含氧量；必須結合交換處所在器官與氧氣資料判斷。", "圖表推理題先用不易改變的定義判流向，再加入氧氣與器官位置限制。", ["先用離開或回到心臟判定動脈與靜脈。", "不要把名稱直接等同含氧量。", "找出交換處是在全身組織或肺部。", "再用氧氣變化檢查體循環或肺循環。", "所以選 A。"], "hard"),
    make(10, "要解釋心臟、血管與血液如何合作維持細胞活動，哪種模型最完整？", {"A": "心臟提供推動，血管提供單向與分流路徑，血液攜帶物質，微血管完成交換", "B": "只畫心臟，不必標示血管與血液成分", "C": "把所有交換都畫在主動脈內，細胞不需接觸微血管", "D": "把心臟當成製造氧與消化食物的單一器官"}, "循環系統是合作系統：心臟推動、血管導流與分流、血液運輸，微血管在組織附近交換；只畫單一器官無法說明完整功能。", "整合題用『推動—路徑—載體—交換』四個角色逐項檢查。", ["先指出心臟提供血液流動的推動力。", "再標示血管形成的單向與分流路徑。", "把氧、養分、二氧化碳和廢物放入血液運輸。", "最後把交換位置放在組織附近微血管。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
